-- itemdesc_i18n_core.lua: the description line of an item in the language of the player who looks at it.
-- The item carries one description text (items.xml, or an attribute a script wrote): English, shared by all players.
-- The look callback (itemdesc_i18n.lua) and the rich tooltip (item_tooltip.lua) swap that text for the player's
-- language:
--   1. a unique: ChaosUniqueDescPt (generated by tools/gen_unique_specs.py from unique_flavor_pt.tsv), exact text;
--   2. the whole text through `tr` (Chaos.tx: an exact key, else a template key such as "%d uses left");
--   3. else sentence by sentence (a text is often several sentences, some of them shared with other items). A
--      sentence with numbers is also tried with its numbers as %d ("Quality: +5%" -> "Quality: +%d%%"), and the
--      modifier lists of a rolled item ("Prefixes: Sword +2 (T3); Fire +5% dmg (T2)") one modifier at a time.
-- Pure logic: `tr` is injected (text -> translation, or the same text when there is none), so the unit test
-- (tests/itemdesc_i18n_test.lua) runs without the engine.
ChaosItemDescI18n = ChaosItemDescI18n or {}
local D = ChaosItemDescI18n
local unpack = table.unpack or unpack

-- split a text into sentences and the separators between them, so that table.concat(D.split(t)) == t. Odd entries
-- are sentences, even entries separators (". " keeps its dot in the sentence; a line break is a separator).
function D.split(text)
	local parts, pos = {}, 1
	while pos <= #text do
		local a, b = text:find("[%.!%?] +", pos)
		local n = text:find("\n+", pos)
		if not a and not n then
			break
		end
		if a and (not n or a < n) then
			parts[#parts + 1] = text:sub(pos, a)
			parts[#parts + 1] = text:sub(a + 1, b) -- the blanks
			pos = b + 1
		else
			local _, e = text:find("\n+", n)
			parts[#parts + 1] = text:sub(pos, n - 1)
			parts[#parts + 1] = text:sub(n, e)
			pos = e + 1
		end
	end
	if pos <= #text then
		parts[#parts + 1] = text:sub(pos)
	end
	return parts
end

-- the text with every number as %d (a literal % written %%), and the numbers: "Quality: +5%" -> "Quality: +%d%%", {5}
function D.normalize(text)
	local nums = {}
	local key = text:gsub("%%", "%%%%"):gsub("%d+", function(d)
		nums[#nums + 1] = tonumber(d)
		return "%d"
	end)
	return key, nums
end

-- the text through its numberless key; nil when there is no digit or no translation
local function viaNumbers(text, tr)
	local key, nums = D.normalize(text)
	if #nums == 0 then
		return nil
	end
	local pattern = tr(key)
	if pattern == key or type(pattern) ~= "string" then
		return nil
	end
	local ok, out = pcall(string.format, pattern, unpack(nums))
	return ok and out or nil
end

-- one piece of text (a sentence, a modifier): the translation or nil
local function lookup(text, tr)
	local t = tr(text)
	if t ~= text then
		return t
	end
	return viaNumbers(text, tr)
end

-- a sentence keeps its closing dot, the keys of numbered texts often have none ("Quality: +%d%%")
local function piece(text, tr)
	local t = lookup(text, tr)
	if t then
		return t
	end
	local body = text:match("^(.-)%.$")
	if body and body ~= "" then
		t = lookup(body, tr)
		return t and (t .. ".") or nil
	end
	return nil
end

-- "Sword +2 (T3); Fire +5% dmg (T2, bound)" -> each modifier on its own, the tier suffix kept
local function modList(list, tr, sep)
	sep = sep or "; "
	local out, changed = {}, false
	for mod in (list .. sep):gmatch("(.-)" .. sep:gsub("%p", "%%%0")) do
		local base, tier = mod:match("^(.-)( %(T%d+.-%))$")
		if not base then
			-- the tier of a rift modifier is a Roman numeral: "Monsters have +45% health (II)"
			base, tier = mod:match("^(.-)( %([IVX]+%))$")
		end
		base = base or mod
		local t = piece(base, tr)
		if t then
			changed = true
		end
		tier = tier or ""
		if tier:find(", bound", 1, true) then
			local bound = tr(", bound")
			tier = tier:gsub(", bound", (bound:gsub("%%", "%%%%")))
		end
		out[#out + 1] = (t or base) .. tier
	end
	return changed and table.concat(out, sep) or nil
end

-- the lists of labelled sentences; a rift key lists "Modifiers: a (II); b (I)." and "Rewards: +3% x, +5% y."
local LISTS = {"Corrupted implicit:", "Prefixes:", "Suffixes:", "Modifiers:", "Rewards:"}
local LIST_SEP = {["Rewards:"] = ", "}

-- a sentence: the translation or nil
local function sentence(text, tr)
	local t = piece(text, tr)
	if t then
		return t
	end
	for _, label in ipairs(LISTS) do
		if text:sub(1, #label) == label then
			local rest = text:sub(#label + 1):gsub("^ +", "")
			-- bracketed upgrade slots behind the last modifier ("[Attack+2]") stay as they are
			local slots = ""
			local head, tail = rest:match("^(.-)( %[.*)$")
			if head then
				rest, slots = head, tail
			end
			local dot = rest:match("%.$") and "." or ""
			local list = modList(dot ~= "" and rest:sub(1, -2) or rest, tr, LIST_SEP[label])
			if list then
				return tr(label) .. " " .. list .. dot .. slots
			end
		end
	end
	-- "Head: tail" with each side known on its own ("World modifier of the week: Undead give 30% more ...")
	local head, tail = text:match("^(.-): (.+)$")
	if head and head ~= "" then
		local h, t = piece(head, tr), piece(tail, tr)
		if h or t then
			return (h or head) .. ": " .. (t or tail)
		end
	end
	return nil
end

-- the text in the player's language (or `text` itself when nothing is known)
function D.translate(text, tr, uniques)
	if type(text) ~= "string" or text == "" then
		return text
	end
	local u = uniques and uniques[text]
	if u then
		return u
	end
	local parts = D.split(text)
	local out, changed, whole_ok = {}, false, true
	for i, part in ipairs(parts) do
		if i % 2 == 1 and part:find("%a") then
			local t = sentence(part, tr)
			if t then
				changed = true
			else
				whole_ok = false
			end
			out[#out + 1] = t or part
		else
			out[#out + 1] = part
		end
	end
	-- every sentence known: the sentence by sentence text (a whole-text template ending in %s, such as "It hums with
	-- the name %s", would swallow the sentences behind it and leave them in English)
	if #parts > 1 and whole_ok and changed then
		return table.concat(out)
	end
	local whole = tr(text)
	if whole ~= text then
		return whole
	end
	if #parts == 0 then
		return text
	end
	return changed and table.concat(out) or text
end

-- the look description with `raw` (the English description of the item) replaced by its translation. A plain find:
-- the description holds other lines ("You see ...", weight) that stay as the engine wrote them.
function D.apply(description, raw, tr, uniques)
	if type(description) ~= "string" or type(raw) ~= "string" or raw == "" then
		return description
	end
	local text = D.translate(raw, tr, uniques)
	if text == raw then
		return description
	end
	local a, b = description:find(raw, 1, true)
	if not a then
		return description
	end
	return description:sub(1, a - 1) .. text .. description:sub(b + 1)
end

return D
